import (
	"fmt"
)

resp, err := client.Countries().ListCountries(ctx, map[string]any{"search": "aus"}, nil)
if err != nil {
	log.Fatal(err)
}
for _, row := range resp.Map().(map[string]any)["countries"].([]any) {
	country := row.(map[string]any)
	fmt.Println(country["id"], country["code"], country["name"], country["state_count"])
}

